#!/bin/sh
pacman_menu(){ while :; do c=$(ui_menu Pacman 'Arch package configuration.' conf 'Edit pacman.conf' mirrors 'Edit mirrorlist' parallel 'Set parallel downloads' keys 'Initialize/populate keyring' cache 'Clean package cache') || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; case $c in conf) edit_file /etc/pacman.conf;; mirrors) edit_file /etc/pacman.d/mirrorlist;; parallel) n=$(ui_input Pacman 'ParallelDownloads:' 5) || continue; backup_file /etc/pacman.conf; sed -i "s/^#*ParallelDownloads.*/ParallelDownloads = $n/" /etc/pacman.conf;; keys) run_capture Keyring as_root sh -c 'pacman-key --init && pacman-key --populate';; cache) run_capture Cache as_root pacman -Sc;; esac; done; }
